  ('settler', 'colono', 'A person who moves to a new region or country to establish a permanent home, often as part of a colony.', 'The first European settlers arrived in the 17th century.', 'B1', 'noun', 'general-vocabulary', 43593),
  ('tepid', 'morno', 'Only slightly warm; neither hot nor cold.', 'The bath water was tepid and uninviting.', 'B1', 'adjective', 'general-vocabulary', 43604),
  ('sacristy', 'sacristia', 'A room in a church, typically near the altar, where sacred vessels, vestments, and other items used in worship are kept, and where clergy may prepare for services.', 'The priest went to the sacristy to put on his robes before the service.', 'C1', 'noun', 'general-vocabulary', 43606),
  ('indomitable', 'indômito', 'Impossible to subdue or defeat; having a strong, determined spirit.', 'Her indomitable will helped her overcome every obstacle.', 'C1', 'adjective', 'general-vocabulary', 43616),
