  ('prattle', 'tagarelar', 'To speak rapidly and continuously about unimportant or childish things.', 'The children prattled on about their day at school.', 'C1', 'verb', 'general-vocabulary', 43636),
  ('tachycardia', 'taquicardia', 'A medical condition characterized by a heart rate that exceeds 100 beats per minute at rest.', 'The patient was diagnosed with tachycardia after the ECG showed a resting heart rate of 120 bpm.', 'C1', 'noun', 'health', 43637),
  ('runoff', 'escoamento', 'The flow of surplus water or other liquid that exceeds the capacity of the ground or a container, often from rain or melting snow.', 'Heavy rainfall caused significant runoff into the river.', 'B2', 'noun', 'general-vocabulary', 43649),
