  ('anjou', 'Anjou', 'A variety of pear with firm, juicy flesh and a greenish-yellow skin, often used in cooking or eaten fresh.', 'She sliced an Anjou pear for the salad.', 'B1', 'noun', 'general-vocabulary', 43676),
  ('geothermal', 'geotérmico', 'Relating to the thermal energy generated and stored within the Earth''s crust.', 'Geothermal energy is used to heat homes and generate electricity.', 'B2', 'adjective', 'science', 43680),
  ('mummification', 'mumificação', 'The process of preserving a dead body by embalming and drying it, then wrapping it in cloth, as practiced in ancient Egypt and other cultures.', 'The ancient Egyptians perfected the art of mummification to preserve bodies for the afterlife.', 'B2', 'noun', 'health', 43684),
  ('billet', 'aquartelar', 'To assign or provide accommodation for soldiers, especially in private homes or civilian buildings.', 'The army billeted the troops in the village during the winter.', 'B2', 'verb', 'general-vocabulary', 43695),
