  ('precipitation', 'precipitação', 'Any form of water, such as rain, snow, sleet, or hail, that falls from the atmosphere to the Earth''s surface.', 'The forecast predicts heavy precipitation for the weekend.', 'B1', 'noun', 'science', 43716),
  ('podiatrist', 'podólogo', 'A medical professional who diagnoses and treats conditions and injuries of the feet and lower legs.', 'She visited a podiatrist for her persistent heel pain.', 'B2', 'noun', 'health', 43728),
  ('nutritionist', 'nutricionista', 'A professional who specializes in the study of food, nutrients, and their effects on health and well-being.', 'The nutritionist recommended a balanced diet rich in vegetables.', 'B2', 'noun', 'health', 43729),
  ('homelessness', 'desabrigo', 'The condition of lacking a fixed, regular, and adequate nighttime residence, often resulting in living in public spaces or shelters.', 'Homelessness is a growing problem in many major cities.', 'B2', 'noun', 'general-vocabulary', 43739),
  ('anise', 'anis', 'A plant native to Egypt and the Mediterranean region, cultivated for its aromatic seeds and oil, used in cooking and medicine.', 'Anise is often used to flavor breads and pastries.', 'B1', 'noun', 'food', 43750),
  ('squall', 'borrasca', 'A sudden, strong, and often violent gust of wind, frequently accompanied by rain, snow, or sleet.', 'A sudden squall hit the coast, capsizing several small boats.', 'B2', 'noun', 'general-vocabulary', 43756),
  ('symbiosis', 'simbiose', 'A close, long-term interaction between two different biological organisms where both benefit from the association.', 'The relationship between bees and flowers is a classic example of symbiosis.', 'B2', 'noun', 'science', 43763),
  ('appalachian', 'apalachiano', 'Of or relating to the Appalachian Mountains or the cultural region of Appalachia in the eastern United States.', 'The Appalachian Trail is a famous hiking route.', 'B2', 'adjective', 'general-vocabulary', 43782),
  ('vulva', 'vulva', 'The external parts of the female reproductive system, including the labia, clitoris, and vaginal opening.', 'The doctor explained the anatomy of the vulva during the consultation.', 'B2', 'noun', 'health', 43796),
