  ('automaton', 'autômato', 'A self-operating machine or mechanism that performs tasks automatically, often resembling a human or animal.', 'The museum displayed an antique automaton that could write.', 'B2', 'noun', 'general-vocabulary', 43838),
  ('anti-american', 'antiamericano', 'Expressing or feeling opposition, hostility, or criticism towards the United States, its government, culture, or policies.', 'The protest was fueled by anti-American sentiment.', 'B2', 'adjective', 'politics', 43845),
  ('canasta', 'canastra', 'A card game similar to rummy, played with two decks of cards and four jokers, where jokers and twos are wild cards, and the goal is to form melds of cards of the same rank.', 'They spent the evening playing canasta with friends.', 'B2', 'noun', 'general-vocabulary', 43858),
