  ('childishness', 'criancice', 'A quality or property characteristic of a child, often implying innocence or immaturity.', 'Her childishness was endearing to her grandparents.', 'B2', 'noun', 'general-vocabulary', 43911),
  ('insinuation', 'insinuação', 'An indirect, often unpleasant or malicious, hint or suggestion about something.', 'She made an insinuation about his honesty without any proof.', 'C1', 'noun', 'general-vocabulary', 43923),
  ('ream', 'resma', 'A standard unit for measuring paper, typically 480 or 500 sheets, or 20 quires.', 'The office ordered several reams of A4 paper for the printer.', 'B1', 'noun', 'general-vocabulary', 43927),
  ('bespoke', 'sob medida', 'Made to the customer''s specific requirements, especially for clothing.', 'He wore a bespoke suit to the wedding.', 'B2', 'adjective', 'general-vocabulary', 43933),
  ('mezzanine', 'mezanino', 'A low-ceilinged floor between two main floors of a building, typically between the ground and first floor.', 'The office is located on the mezzanine level.', 'B2', 'noun', 'general-vocabulary', 43940),
