  ('self-discipline', 'autodisciplina', 'The ability to control one''s own behavior, emotions, and desires, especially in difficult situations.', 'Self-discipline is essential for achieving long-term goals.', 'B2', 'noun', 'general-vocabulary', 44316),
  ('chide', 'ralhar', 'To express mild disapproval or criticism; to scold gently.', 'The teacher chided the student for being late to class.', 'C1', 'verb', 'general-vocabulary', 44324),
  ('knead', 'sovar', 'To work and press a mixture, such as dough, into a uniform and pliable mass by folding, pressing, and stretching with the hands.', 'She kneaded the bread dough for ten minutes until it became smooth.', 'A2', 'verb', 'food', 44325),
