  ('record-breaking', 'recorde', 'Exceeding any previously established record or achievement.', 'The athlete achieved a record-breaking time in the 100-meter dash.', 'B2', 'adjective', 'sports', 44346),
  ('evaporation', 'evaporação', 'The process by which a liquid turns into a vapor or gas, usually due to heat.', 'The evaporation of water from the lake is faster in summer.', 'B2', 'noun', 'science', 44349),
  ('palatial', 'suntuoso', 'Of, relating to, or resembling a palace in size, splendor, or grandeur.', 'The palatial estate was surrounded by lush gardens.', 'B2', 'adjective', 'general-vocabulary', 44352),
