  ('inorganic', 'inorgânico', 'Relating to or belonging to the class of compounds that do not have a carbon basis.', 'Inorganic chemistry deals with substances like metals and minerals.', 'B2', 'adjective', 'science', 46416),
  ('erogenous', 'erógeno', 'Describes areas of the body that are particularly responsive to sexual touch or arousal.', 'The neck is often considered an erogenous zone.', 'C1', 'adjective', 'health', 46417),
  ('hookah', 'arguile', 'An Eastern smoking device where tobacco smoke is cooled by passing through water before being inhaled through a flexible tube.', 'They sat in the cafe sharing a hookah with flavored tobacco.', 'B2', 'noun', 'general-vocabulary', 46423),
  ('chronicler', 'cronista', 'A person who writes down and records historical events in a detailed and chronological manner.', 'The medieval chronicler documented the king''s reign in great detail.', 'C1', 'noun', 'general-vocabulary', 46439),
  ('irregularity', 'irregularidade', 'Behavior that violates established rules, etiquette, customs, or moral standards.', 'The audit revealed several financial irregularities in the company''s accounts.', 'B2', 'noun', 'general-vocabulary', 46442),
  ('downturn', 'declínio', 'A period of reduced economic activity, often characterized by falling prices, lower production, and increased unemployment.', 'The country experienced a severe economic downturn last year.', 'B2', 'noun', 'business', 46444),
  ('cuteness', 'fofura', 'The quality of being attractive in a delicate, graceful, or endearing way, often associated with young women or girls.', 'Her cuteness made her the center of attention at the party.', 'A2', 'noun', 'general-vocabulary', 46466),
  ('resourcefulness', 'engenhosidade', 'The quality of being able to cope effectively with difficult or unexpected situations.', 'Her resourcefulness helped the team survive the crisis.', 'B2', 'noun', 'general-vocabulary', 46472),
  ('misadventure', 'desventura', 'An unlucky event or accident, often causing harm or trouble.', 'The hiker''s misadventure in the mountains required a rescue team.', 'B2', 'noun', 'general-vocabulary', 46480),
  ('purist', 'purista', 'A person who insists on strict adherence to traditional rules or structures, especially in language or art.', 'The grammar purist corrected every minor mistake in the essay.', 'C1', 'noun', 'general-vocabulary', 46482),
  ('gaussian', 'gaussiano', 'Describing concepts, distributions, functions, or methods named after Carl Friedrich Gauss, used in mathematics, physics, astronomy, and probability.', 'The Gaussian distribution is fundamental in statistics.', 'C1', 'adjective', 'science', 46484),
  ('carbonara', 'carbonara', 'A rich Italian pasta dish made with eggs, hard cheese (like Pecorino or Parmesan), cured pork (guanciale or pancetta), and black pepper.', 'She ordered spaghetti carbonara at the Italian restaurant.', 'A2', 'noun', 'food', 46504),
  ('zloty', 'zlóti', 'The official monetary unit of Poland, subdivided into 100 groszy.', 'The price of the book is 30 zloty.', 'B1', 'noun', 'general-vocabulary', 46505),
  ('agora', 'ágora', 'A central public space in ancient Greek city-states used for markets, political gatherings, and social activities.', 'The agora was the heart of Athenian public life.', 'B2', 'noun', 'general-vocabulary', 46510),
  ('impulsively', 'impulsivamente', 'In a way that is done suddenly without thinking about the consequences.', 'She impulsively bought an expensive dress she didn''t need.', 'B2', 'adverb', 'general-vocabulary', 46518),
  ('aberrant', 'aberrante', 'Departing from an accepted standard or usual behavior; abnormal.', 'The scientist noted the aberrant results in the experiment.', 'C1', 'adjective', 'general-vocabulary', 46525),
  ('suffrage', 'sufrágio', 'The legal right to vote in political elections, a fundamental right in democratic societies.', 'The 19th Amendment granted women suffrage in the United States.', 'B2', 'noun', 'general-vocabulary', 46535),
  ('exhibitionist', 'exibicionista', 'A person who has a compulsive urge to expose their genitals in public, typically as a form of sexual gratification.', 'The park has signs warning about a known exhibitionist in the area.', 'C1', 'noun', 'health', 46542),
  ('harmonium', 'harmônio', 'A free-reed musical instrument where air is pushed through reeds by bellows, often used in Indian classical music and devotional songs.', 'He played the harmonium during the bhajan session.', 'B2', 'noun', 'arts', 46548),
  ('mountaineering', 'alpinismo', 'The sport or activity of climbing mountains, often involving technical skills and equipment.', 'Mountaineering requires physical strength and mental endurance.', 'B2', 'noun', 'sports', 46553),
  ('antagonistic', 'antagônico', 'Showing opposition or resistance to something or someone.', 'The two political parties remained antagonistic toward each other.', 'B2', 'adjective', 'general-vocabulary', 46561),
  ('by-election', 'eleição suplementar', 'An election held between regular general elections to fill a vacant political office.', 'The by-election was called after the MP resigned unexpectedly.', 'B2', 'noun', 'general-vocabulary', 46569),
  ('self-awareness', 'autoconsciência', 'The ability to recognize and understand your own emotions, thoughts, and values, and how they influence your behavior.', 'Self-awareness is the first step toward personal growth.', 'B2', 'noun', 'general-vocabulary', 46577),
  ('foul-mouthed', 'desbocado', 'Characterized by the frequent use of vulgar, obscene, or profane words.', 'The coach was known for being foul-mouthed during games.', 'B2', 'adjective', 'general-vocabulary', 46592),
  ('inbreeding', 'endocruzamento', 'The process of breeding or mating between individuals who are closely related genetically, such as siblings or cousins.', 'Inbreeding among certain animal populations can lead to genetic defects.', 'C1', 'noun', 'science', 46598),
  ('pornographer', 'pornógrafo', 'A person who creates, publishes, or sells sexually explicit content, often in violation of community standards.', 'The court convicted the pornographer for distributing obscene materials.', 'C1', 'noun', 'general-vocabulary', 46619),
  ('cardiomyopathy', 'cardiomiopatia', 'A disease of the heart muscle that makes it harder for the heart to pump blood to the rest of the body.', 'The patient was diagnosed with dilated cardiomyopathy.', 'C1', 'noun', 'health', 46627),
  ('linkage', 'ligamento', 'The tendency of genes located close together on a chromosome to be inherited together during meiosis.', 'Genetic linkage analysis helps map the location of disease genes.', 'C1', 'noun', 'science', 46641),
  ('philosophically', 'filosoficamente', 'In a way that relates to the study of philosophy or deep thinking about existence, knowledge, and values.', 'She spoke philosophically about the meaning of life.', 'C1', 'adverb', 'general-vocabulary', 46652),
  ('candidly', 'candidamente', 'Speaking or writing in an honest, open, and straightforward manner, without hiding anything.', 'She spoke candidly about her struggles with anxiety.', 'C1', 'adverb', 'general-vocabulary', 46653),
  ('bludgeon', 'clava', 'A short, thick, heavy stick used as a weapon, typically made of wood or metal.', 'The attacker was armed with a heavy bludgeon.', 'B2', 'noun', 'general-vocabulary', 46671),
  ('chlorophyll', 'clorofila', 'A group of green pigments found in the chloroplasts of plants and other photosynthetic organisms, essential for absorbing light energy during photosynthesis.', 'Chlorophyll gives leaves their green color.', 'B2', 'noun', 'science', 46676),
  ('waxy', 'ceroso', 'Composed of or coated with a layer of wax.', 'The waxy surface of the candle reflected the light.', 'B1', 'adjective', 'general-vocabulary', 46682),
  ('individualism', 'individualismo', 'A philosophy that emphasizes personal independence and the importance of the individual over the collective.', 'Individualism is a core value in many Western societies.', 'C2', 'noun', 'general-vocabulary', 46699),
  ('massager', 'massageador', 'An electrical or manual device designed to apply pressure and vibration to the body for therapeutic or relaxation purposes.', 'She bought a handheld massager for her neck pain.', 'A2', 'noun', 'general-vocabulary', 46702),
  ('tassel', 'borla', 'An ornament made of a bunch of threads or cords tied together at one end and hanging loose at the other, used to decorate clothing, curtains, or hats.', 'The graduation cap had a gold tassel hanging from it.', 'B1', 'noun', 'general-vocabulary', 46705),
  ('amass', 'amontoar', 'To gather or collect a large amount of something, especially money or goods.', 'He amassed a fortune through smart investments.', 'B2', 'verb', 'general-vocabulary', 46713),
  ('sniffle', 'fungar', 'To cry or whine while making snuffling sounds, often due to a cold or sadness.', 'The child sniffled after falling off the swing.', 'B1', 'verb', 'general-vocabulary', 46725),
  ('minimalist', 'minimalista', 'An artist or practitioner who advocates or works in the style of minimalism, characterized by simplicity and the use of minimal elements.', 'The minimalist used only black and white in his paintings.', 'B2', 'noun', 'arts', 46751),
  ('honeydew', 'melada', 'A sweet, sticky liquid excreted by aphids and other insects, often found on plant leaves.', 'The leaves were covered in honeydew from the aphids.', 'B2', 'noun', 'general-vocabulary', 46753),
  ('surrealism', 'surrealismo', 'A 20th-century avant-garde movement in art and literature that sought to release the creative potential of the unconscious mind, often by combining unrelated or dreamlike images in unexpected ways.', 'Salvador Dalí is one of the most famous painters associated with surrealism.', 'C2', 'noun', 'arts', 46756),
  ('metaphysics', 'metafísica', 'The branch of philosophy that deals with the fundamental nature of reality, existence, causality, and the relationship between mind and matter.', 'Aristotle''s work on metaphysics laid the foundation for Western philosophy.', 'C1', 'noun', 'science', 46759),
  ('archivist', 'arquivista', 'A professional responsible for collecting, organizing, preserving, and cataloging historical records and documents.', 'The archivist carefully restored the ancient manuscripts.', 'B2', 'noun', 'general-vocabulary', 46774),
  ('bluish', 'azulado', 'Somewhat blue in color; having a shade or tinge of blue.', 'The sky took on a bluish hue just before sunset.', 'A2', 'adjective', 'general-vocabulary', 46776),
  ('crochet', 'crochetar', 'To make a piece of fabric or clothing using a hooked needle (crochet hook) to interlock loops of yarn.', 'She learned to crochet a scarf for her mother.', 'B1', 'verb', 'general-vocabulary', 46783),
  ('mobilise', 'mobilizar', 'To assemble and prepare military personnel for active service.', 'The government mobilised the army in response to the threat.', 'B2', 'verb', 'general-vocabulary', 46792),
  ('kirsch', 'kirsch', 'A clear, colorless brandy distilled from the fermented juice of black morello cherries, typically produced in Germany, France, and Switzerland.', 'He added a splash of kirsch to the chocolate fondue.', 'B2', 'noun', 'food', 46802),
  ('alsatian', 'alsaciano', 'Of or relating to the Alsace region of France, its people, or its culture.', 'The Alsatian dialect is spoken in parts of eastern France.', 'B2', 'adjective', 'general-vocabulary', 46804),
  ('marquess', 'marquês', 'A nobleman ranking above a count in various European countries.', 'The marquess inherited the title from his father.', 'C1', 'noun', 'general-vocabulary', 46806),
  ('spurious', 'espúrio', 'Not genuine, authentic, or true; made to look like something it is not.', 'The document was rejected because it contained spurious signatures.', 'C2', 'adjective', 'general-vocabulary', 46826),
  ('onyx', 'ônix', 'A type of chalcedony (a variety of quartz) characterized by parallel bands of alternating colors, most commonly black and white, often used in jewelry and cameo carving.', 'The artisan carved a beautiful cameo from a piece of black and white onyx.', 'B2', 'noun', 'arts', 46830),
  ('tumult', 'tumulto', 'A state of confusion, noise, and disorder, often involving a crowd.', 'The city was in a tumult after the announcement.', 'B2', 'noun', 'general-vocabulary', 46851),
  ('asexual', 'assexual', 'Describing reproduction or processes that do not involve the union of male and female gametes.', 'Many plants reproduce through asexual methods like budding.', 'B2', 'adjective', 'science', 46888),
  ('saucepan', 'panela', 'A deep metal cooking pot with a long handle and often a lid, used for boiling, stewing, or making sauces.', 'She heated the milk in a small saucepan.', 'B1', 'noun', 'food', 46893),
  ('precede', 'preceder', 'To happen or exist before something else.', 'The storm was preceded by a period of calm.', 'B2', 'verb', 'general-vocabulary', 46896),
  ('absorbent', 'absorvente', 'Describes a material that can take in or soak up liquids or moisture effectively.', 'Paper towels are highly absorbent and great for cleaning spills.', 'B1', 'adjective', 'technical', 46900),
  ('lichen', 'líquen', 'A composite organism that arises from algae or cyanobacteria living among filaments of multiple fungi species in a mutualistic relationship, commonly found as crusty or bushy growths on trees, rocks, or bare ground.', 'The old stone wall was covered in patches of grey and orange lichen.', 'B2', 'noun', 'science', 46912),
  ('mangle', 'desfigurar', 'To change or distort something, such as words or information, so badly that it becomes unclear or unrecognizable.', 'He mangled the pronunciation of the foreign name.', 'C2', 'verb', 'general-vocabulary', 46913),
  ('moneylender', 'agiota', 'An individual or entity that provides loans, typically charging very high interest rates, often considered exploitative.', 'The moneylender demanded repayment with exorbitant interest.', 'B2', 'noun', 'general-vocabulary', 46915),
  ('nimbus', 'nimbo', 'A large, dark grey cloud that typically brings rain or stormy weather.', 'Dark nimbus clouds gathered on the horizon before the storm.', 'B2', 'noun', 'general-vocabulary', 46921),
  ('harmonize', 'harmonizar', 'To sing or play in harmony with others, creating a pleasing combination of notes.', 'The choir members harmonized beautifully during the concert.', 'B2', 'verb', 'general-vocabulary', 46929),
  ('dacha', 'dacha', 'A seasonal or year-round second home, often located in the countryside, used by many people in Russia and other post-Soviet states for gardening, relaxation, and family gatherings.', 'Every summer, the family retreats to their dacha outside Moscow.', 'B2', 'noun', 'general-vocabulary', 46934),
  ('gestation', 'gestação', 'The period during which an embryo or fetus develops inside the womb, typically about 266 days in humans.', 'The average human gestation period lasts around 40 weeks.', 'B2', 'noun', 'health', 46936),
  ('deaf-mute', 'surdo-mudo', 'A person who is both deaf and unable to speak. This term is now often considered outdated and potentially offensive; preferred terms include ''deaf'' or ''deaf and hard of hearing'' when referring to individuals who do not use spoken language.', 'Historically, the term ''deaf-mute'' was used in medical records.', 'B2', 'noun', 'general-vocabulary', 46940),
  ('contrite', 'contrito', 'Feeling or expressing sincere regret for a wrongdoing or fault.', 'He was contrite after breaking his friend''s favorite vase.', 'C1', 'adjective', 'general-vocabulary', 46947),
  ('quash', 'cassar', 'To legally declare a decision, judgment, or order invalid.', 'The judge quashed the previous verdict due to new evidence.', 'C1', 'verb', 'general-vocabulary', 46948),
  ('quesadilla', 'quesadilha', 'A Mexican dish consisting of a tortilla filled primarily with cheese, then heated until the cheese melts, often folded and sometimes containing additional ingredients.', 'She ordered a chicken quesadilla for lunch.', 'A2', 'noun', 'food', 46956),
  ('domicile', 'domicílio', 'The place where a person has their permanent home or principal residence, often used in legal contexts.', 'His domicile is registered in New York for tax purposes.', 'C1', 'noun', 'general-vocabulary', 46963),
  ('thoroughfare', 'passagem', 'A main road or public way that connects one place to another, often used for travel or transport.', 'The city''s main thoroughfare was closed for repairs.', 'B2', 'noun', 'general-vocabulary', 46965),
  ('straddle', 'montar', 'To sit or stand with one leg on each side of something.', 'He straddled the horse with ease.', 'B2', 'verb', 'general-vocabulary', 46979),
  ('trellis', 'treliça', 'A framework of latticework used to support and train climbing plants.', 'The roses climbed up the wooden trellis in the garden.', 'B1', 'noun', 'general-vocabulary', 46985),
  ('solidly', 'solidamente', 'In a way that is physically strong, stable, and not likely to move or break.', 'The table was solidly built from oak wood.', 'B2', 'adverb', 'general-vocabulary', 46988),
  ('proliferation', 'proliferação', 'The process of growing or increasing quickly through the production of new parts or cells.', 'The proliferation of cancer cells requires immediate treatment.', 'C2', 'noun', 'general-vocabulary', 47002),
  ('asphyxia', 'asfixia', 'A condition where the body is deprived of an adequate supply of oxygen, often due to an inability to breathe properly.', 'The autopsy report listed asphyxia as the cause of death.', 'C1', 'noun', 'health', 47017),
  ('muskrat', 'onDatra', 'A medium-sized, beaver-like rodent native to North America, known for its glossy, dark brown fur and its ability to live in wetlands.', 'The muskrat built its lodge among the cattails in the marsh.', 'B1', 'noun', 'general-vocabulary', 47019),
  ('tincture', 'tintura', 'A substance used to give color to metals, especially in heraldry or metalworking.', 'The artisan applied a tincture to the silver to give it a golden hue.', 'C1', 'noun', 'health', 47021),
  ('gruelling', 'exaustivo', 'Requiring a very large amount of physical effort that leads to extreme tiredness.', 'The soldiers endured a gruelling training march in the desert.', 'C1', 'adjective', 'general-vocabulary', 47035),
  ('additive', 'aditivo', 'Relating to a substance added to something, such as food, fuel, paint, or medicine, to improve or alter its properties.', 'The additive properties of this chemical improve the fuel''s efficiency.', 'C2', 'adjective', 'technical', 47042),
  ('twiddle', 'girar', 'A series of small, often aimless or nervous twists or turns, especially of the fingers or hands.', 'He gave his pen a nervous twiddle while waiting for the interview.', 'C1', 'noun', 'general-vocabulary', 47052),
  ('parochial', 'paroquial', 'Relating to a church parish or its affairs.', 'The parochial council meets every month to discuss church matters.', 'C2', 'adjective', 'general-vocabulary', 47071),
  ('singe', 'chamuscar', 'To burn the surface of something slightly, often removing hair or feathers.', 'He singed the chicken over the flame to remove the pinfeathers.', 'C2', 'verb', 'general-vocabulary', 47085),
  ('leathery', 'coriáceo', 'Having a tough, flexible texture similar to leather.', 'The old man''s hands had a leathery feel from years of work.', 'B2', 'adjective', 'general-vocabulary', 47090),
  ('discus', 'disco', 'A heavy, flat, circular object thrown by athletes in track and field competitions.', 'The athlete threw the discus over 60 meters.', 'B1', 'noun', 'sports', 47112),
  ('squiggly', 'sinuoso', 'Having a shape or pattern that is full of irregular curves and twists.', 'The child drew a squiggly line across the paper.', 'B1', 'adjective', 'general-vocabulary', 47114),
  ('flotsam', 'destroços', 'The wreckage of a ship or its cargo found floating on the sea.', 'The beach was covered with flotsam after the storm.', 'C1', 'noun', 'general-vocabulary', 47120),
  ('fidget', 'inquieto', 'A person who makes small, restless movements, especially due to nervousness or boredom.', 'He''s such a fidget; he can''t sit still for a minute.', 'B1', 'noun', 'general-vocabulary', 47122),
  ('transcendence', 'transcendência', 'A state of being or existence that extends above and beyond the limits of ordinary material experience.', 'The philosopher spoke of the soul''s transcendence of the physical world.', 'C1', 'noun', 'general-vocabulary', 47123),
  ('ulster', 'ulster', 'A loose, long overcoat made from heavy fabric, often with a belt, originally from Ulster, Ireland.', 'He wore a tweed ulster to protect against the cold wind.', 'C1', 'noun', 'general-vocabulary', 47134),
  ('geranium', 'gerânio', 'A popular garden plant with rounded leaves and clusters of red, pink, or white flowers.', 'She planted red geraniums in the window boxes.', 'B1', 'noun', 'science', 47152),
  ('lemming', 'lêmingue', 'A small, short-tailed, furry-footed rodent found in Arctic and subarctic regions, known for periodic population booms.', 'Lemmings are known for their dramatic population cycles.', 'B2', 'noun', 'general-vocabulary', 47165),
  ('pigskin', 'pele de porco', 'The tanned hide of a pig, used for making various items such as gloves, shoes, and saddles.', 'The gloves were made of high-quality pigskin.', 'B2', 'noun', 'general-vocabulary', 47166),
  ('reuse', 'reusar', 'To use something again, often after cleaning, repairing, or reprocessing it, rather than discarding it.', 'We can reuse the glass bottles after washing them.', 'B1', 'verb', 'general-vocabulary', 47174),
  ('incandescent', 'incandescente', 'Producing light as a result of being heated to a high temperature.', 'The incandescent bulb glowed warmly in the room.', 'C1', 'adjective', 'technical', 47186),
  ('prideful', 'soberbo', 'Having or showing an exaggerated sense of one''s own importance, often accompanied by a disdain for others.', 'His prideful attitude made him unpopular among his colleagues.', 'B2', 'adjective', 'general-vocabulary', 47195),
  ('nightstick', 'porrete', 'A short, thick stick carried by law enforcement officers for self-defense and crowd control.', 'The officer carried a nightstick on his belt.', 'B2', 'noun', 'general-vocabulary', 47214),
  ('versatility', 'versatilidade', 'The ability to adapt or be adapted to many different functions or activities; having a wide variety of skills.', 'Her versatility as an actress allows her to play both comedic and dramatic roles.', 'C1', 'noun', 'general-vocabulary', 47225),
  ('stiffen', 'endurecer', 'To become physically rigid or less flexible, often due to cold, fear, or injury.', 'Her muscles stiffened after the long run.', 'C1', 'verb', 'general-vocabulary', 47238),
  ('ingestion', 'ingestão', 'The act of taking food, drink, or another substance into the body through the mouth.', 'Proper ingestion of nutrients is essential for good health.', 'B2', 'noun', 'health', 47249),
  ('displace', 'deslocar', 'To force something or someone out of its usual or original position.', 'The earthquake displaced thousands of people from their homes.', 'B2', 'verb', 'general-vocabulary', 47250),
  ('adulteress', 'adúltera', 'A married woman who voluntarily engages in sexual relations with someone other than her spouse.', 'The novel tells the story of an adulteress in a small town.', 'C1', 'noun', 'general-vocabulary', 47256),
  ('congenial', 'amigável', 'Having a pleasant, friendly, and agreeable personality or atmosphere.', 'She is a congenial host who makes everyone feel welcome.', 'B2', 'adjective', 'general-vocabulary', 47277),
  ('mightily', 'poderosamente', 'In a powerful, strong, or forceful manner.', 'He fought mightily against the enemy.', 'B2', 'adverb', 'general-vocabulary', 47292),
  ('allegro', 'allegro', 'A musical term indicating a brisk and lively tempo, typically faster than andante but slower than presto.', 'The symphony''s first movement is marked allegro.', 'B2', 'adjective', 'arts', 47294),
  ('ensue', 'resultar', 'To happen or occur as a result of something else.', 'After the argument, a long silence ensued.', 'B2', 'verb', 'general-vocabulary', 47303),
  ('modular', 'modular', 'Made up of separate, standardized parts or units that can be combined, arranged, or replaced in various ways to allow flexibility and variety in use.', 'The company offers modular furniture that can be rearranged to fit any room.', 'B2', 'adjective', 'technical', 47316),
  ('searchlight', 'holofote', 'A light source equipped with reflectors that projects a strong beam of light in a specific direction, often used for illumination or scanning.', 'The prison used a searchlight to scan the perimeter at night.', 'B2', 'noun', 'general-vocabulary', 47320),
  ('pliable', 'maleável', 'Capable of being bent or shaped without breaking; flexible.', 'The clay is pliable and easy to mold into shapes.', 'B2', 'adjective', 'general-vocabulary', 47321),
  ('condense', 'condensar', 'To make something thicker or more concentrated by removing water or other liquid.', 'The chef condensed the sauce by boiling it for several minutes.', 'B2', 'verb', 'general-vocabulary', 47322),
  ('anthropological', 'antropológico', 'Concerning the scientific study of human societies, cultures, and their development.', 'The research team conducted an anthropological study of the indigenous tribe.', 'C2', 'adjective', 'science', 47323),
  ('chromium', 'cromo', 'A hard, brittle, lustrous, steel-gray metallic element that is highly resistant to corrosion and tarnishing, used in alloys and as a decorative plating.', 'Chromium is added to steel to make it stainless.', 'B2', 'noun', 'science', 47329),
  ('figurative', 'figurativo', 'Using words in a way that is different from their usual meaning to create a special effect or picture in the reader''s mind.', 'The phrase ''a sea of troubles'' is a figurative expression.', 'B2', 'adjective', 'general-vocabulary', 47331),
  ('tarragon', 'estragão', 'A perennial herb with narrow, aromatic leaves, native to southeastern Russia and used in cooking.', 'She added fresh tarragon to the chicken salad for extra flavor.', 'B2', 'noun', 'food', 47334),
  ('predictive', 'preditivo', 'Relating to or having the ability to make predictions about future events or outcomes.', 'The model has strong predictive power for stock market trends.', 'B2', 'adjective', 'technical', 47340),
  ('seashell', 'concha', 'The hard, protective outer covering of a sea creature, such as a mollusk or crustacean.', 'She collected colorful seashells on the beach.', 'A2', 'noun', 'general-vocabulary', 47345),
  ('duality', 'dualidade', 'The state or quality of being made up of two distinct, often opposing, parts or subclasses.', 'The duality of good and evil is a common theme in literature.', 'B2', 'noun', 'science', 47353),
  ('secretion', 'secreção', 'The biological process by which a cell or gland synthesizes and releases a specific substance.', 'The secretion of hormones is regulated by the endocrine system.', 'B2', 'noun', 'science', 47365),
  ('whelp', 'parir', 'To give birth to a puppy or the young of a canid (such as a dog, wolf, or fox).', 'The Labrador whelped a litter of six puppies last night.', 'B2', 'verb', 'general-vocabulary', 47366),
  ('constraint', 'restrição', 'A limitation or restriction that prevents something from happening or being done.', 'Budget constraints forced the company to delay the project.', 'C1', 'noun', 'technical', 47371),
  ('berate', 'repreender', 'To criticize or scold someone in a loud, angry, and lengthy manner.', 'The manager berated the team for missing the deadline.', 'C1', 'verb', 'general-vocabulary', 47372),
  ('debauched', 'libertino', 'Indulging in excessive pleasure, especially involving sex, alcohol, or drugs; morally degraded.', 'The debauched lifestyle of the aristocrats shocked the public.', 'C1', 'adjective', 'general-vocabulary', 47373),
  ('toon', 'desenho', 'A film or television show made by photographing a series of drawings or computer graphics to create the illusion of movement; also refers to a character in such a production.', 'My favorite childhood toon was ''Tom and Jerry''.', 'B1', 'noun', 'general-vocabulary', 47374),
  ('butane', 'butano', 'A colorless, flammable gas that is a component of natural gas and is used as a fuel and in the production of synthetic rubber and other chemicals.', 'Butane is commonly used in portable stoves and lighters.', 'C1', 'noun', 'science', 47375),
  ('nebuchadnezzar', 'Nabucodonosor', 'An extremely large wine bottle that holds the equivalent of 20 standard bottles (approximately 15 liters).', 'The restaurant displayed a nebuchadnezzar of vintage champagne in the window.', 'C1', 'noun', 'general-vocabulary', 47377),
  ('reorganization', 'reorganização', 'The process of imposing a new organization, often involving extensive and drastic changes to how something is arranged or operates.', 'The company underwent a major reorganization to improve efficiency.', 'B2', 'noun', 'business', 47382),
