  ('eradication', 'erradicação', 'The act of completely destroying or eliminating something, especially a disease or problem.', 'The eradication of smallpox is one of the greatest medical achievements.', 'B2', 'noun', 'general-vocabulary', 47556),
  ('gorgonzola', 'gorgonzola', 'A creamy, crumbly Italian blue cheese made from cow''s milk, known for its distinctive greenish-blue veins and strong, tangy flavor.', 'The pasta was topped with crumbled gorgonzola.', 'B1', 'noun', 'food', 47564),
